function shot(r){const x=X,m=M;const el=document.createElement('div');el.className='shot';el.setAttribute('role','dialog');el.setAttribute('aria-label','Screenshot card');
 el.innerHTML=`<div class="hint"><span>Take a screenshot now</span><button class="x" data-close>Close</button></div>
 <div class="box sc"><div class="ch"><h2 class="nm" style="font-size:1.6rem">${esc(x.n)}</h2><div class="cnt">${esc(x.c)}</div></div>
 <p class="sub" style="margin-bottom:8px">${esc(x.u||'')}</p>${stripe(x)}
 <div class="res" style="margin-top:0"><div class="draw"><span class="k">DRAW</span><span class="n">${nf(r.units,1)}</span><span class="u">U</span><span class="ml">= ${nf(r.ml,2)} ml</span></div>
 ${m.kind==='liquid'?'':`<p class="math"><b>${nf(+m.vial,2)} ${vialUnit(m)}</b> + <b>${nf(+m.water,2)} ml BAC</b> = ${m.kind==='iu'?nf(r.conc,0)+' IU':fmtMass(r.conc)}/ml · ${r.per} doses</p>`}
 ${syringe(Math.min(r.units,m.syr),m.syr)}
 <div class="stk">${m.kind==='liquid'?'':`<span class="sk w">${SVG.drop}${nf(+m.water,2)} ML</span>`}<span class="sk d">${SVG.D}${esc(doseLabel(m)).toUpperCase()}</span><span class="sk s">${SVG.syr}${m.kind==='liquid'&&r.syr>1?nf(r.ml,2)+' ML':nf(r.units,1)+' U'}</span>${m.kind==='liquid'?'':`<span class="sk e">${SVG.bin}${fdate(addDays(28)).toUpperCase()}</span>`}</div></div>
 <div class="ft"><span>Mixed ${fdate(new Date())}</span><span>baresignals.co/S/${esc(x.c)}</span></div></div>`;
 document.body.appendChild(el);el.addEventListener('click',e=>{if(e.target.closest('[data-close]'))el.remove()});
 const k=e=>{if(e.key==='Escape'){el.remove();removeEventListener('keydown',k)}};addEventListener('keydown',k)}

/* ---------- v7: swipe a protocol line left to remove it ---------- */
let SW=null,UNDO=null,uT=0;
function undoBar(name){let el=$('.undo');if(!el){el=document.createElement('div');el.className='undo';el.setAttribute('role','status');document.body.appendChild(el)}
 el.innerHTML=`<span>${esc(name)} removed</span><button type="button">Undo</button>`;el.classList.add('on');clearTimeout(uT);uT=setTimeout(()=>{el.classList.remove('on');UNDO=null},5000);
 el.querySelector('button').onclick=()=>{if(UNDO){L.items.splice(Math.min(UNDO.pos,L.items.length),0,UNDO.it);saveL();UNDO=null;render();toast('Back in')}el.classList.remove('on')}}
function clearUndo(old){let el=$('.undo');if(!el){el=document.createElement('div');el.className='undo';el.setAttribute('role','status');document.body.appendChild(el)}
 el.innerHTML=`<span>List cleared</span><button type="button">Undo</button>`;el.classList.add('on');clearTimeout(uT);uT=setTimeout(()=>el.classList.remove('on'),6000);
 el.querySelector('button').onclick=()=>{L.items=old.concat(L.items);saveL();render();toast('Back in');el.classList.remove('on')}}
function removeAt(ix){const items=L.items.filter(i=>IT[i.c]);const it=items[ix];if(!it)return;UNDO={it,pos:L.items.indexOf(it)};L.items=L.items.filter(i=>i!==it);EXP={};saveL();track('scan-swipe-rm');render();undoBar(IT[it.c].n)}
app.addEventListener('touchstart',e=>{const li=e.target.closest('#list .li');if(!li||e.target.closest('input,textarea'))return;const t=e.touches[0];SW={li,x:t.clientX,y:t.clientY,dx:0,on:false}},{passive:true});
app.addEventListener('touchmove',e=>{if(!SW)return;const t=e.touches[0],dx=t.clientX-SW.x,dy=t.clientY-SW.y;
 if(!SW.on){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){SW=null;return}if(dx<-12&&Math.abs(dx)>Math.abs(dy)*1.3){SW.on=true;SW.li.classList.add('sw')}else return}
 SW.dx=Math.min(0,dx);SW.li.style.transform=`translateX(${SW.dx}px)`;SW.li.classList.toggle('go',SW.dx<-SW.li.offsetWidth*.35);e.preventDefault()},{passive:false});
app.addEventListener('touchend',()=>{if(!SW)return;const s=SW;SW=null;if(!s.on)return;
 if(s.dx<-s.li.offsetWidth*.35){s.li.style.transition='transform .18s ease-in';s.li.style.transform='translateX(-110%)';setTimeout(()=>removeAt(+s.li.dataset.ix),170)}
 else{s.li.style.transition='transform .2s';s.li.style.transform='';setTimeout(()=>{s.li.classList.remove('sw','go');s.li.style.transition=''},210)}},{passive:true});
app.addEventListener('touchcancel',()=>{if(SW){SW.li.style.transform='';SW.li.classList.remove('sw','go');SW=null}});
/* rm inside Details also gets Undo */


/* ---------- v10: hold a line to move it up or down, or drop it on the bin ---------- */
let HOLD=null,NOCLICK=false,BIN=null,HOLDAS=0;const HOLD_MS=420;
function binBar(on){if(!BIN){BIN=document.createElement('div');BIN.className='dropbin';BIN.innerHTML=SVG.bin+'<span>Drop here to remove</span>';document.body.appendChild(BIN)}BIN.classList.toggle('on',on);if(!on)BIN.classList.remove('hot')}
function holdStart(li,x,y){if(HOLD)holdEnd(true);HOLD={li,x0:x,y0:y,y,on:false,t:setTimeout(liftLine,HOLD_MS)}}
function liftLine(){const h=HOLD;if(!h)return;
 if(SW){SW.li.style.transform='';SW.li.classList.remove('sw','go');SW=null}
 const lis=$$('#list .li');h.lis=lis;h.ix=lis.indexOf(h.li);if(h.ix<0){HOLD=null;return}
 h.sy=scrollY;h.rects=lis.map(l=>{const r=l.getBoundingClientRect();return {top:r.top+scrollY,h:r.height}});h.to=h.ix;h.on=true;
 h.li.classList.add('lift');lis.forEach(l=>{if(l!==h.li)l.classList.add('shift')});document.body.classList.add('dragging');binBar(true);
 try{navigator.vibrate&&navigator.vibrate(12)}catch(e){}
 HOLDAS=setInterval(()=>{if(!HOLD||!HOLD.on)return;const y=HOLD.y;const binTop=innerHeight-(BIN?BIN.offsetHeight:70);
  if(y<90)scrollBy(0,-9);else if(y>binTop-60&&y<binTop)scrollBy(0,9);else return;holdPaint()},16)}
function holdPaint(){const h=HOLD;if(!h||!h.on)return;const dy=(h.y-h.y0)+(scrollY-h.sy);
 h.li.style.transform=`translateY(${dy}px) scale(1.02)`;
 const r0=h.rects[h.ix],c=r0.top+r0.h/2+dy;let to=h.ix;
 h.rects.forEach((r,i)=>{if(i===h.ix)return;const ci=r.top+r.h/2;if(i<h.ix&&c<ci)to=Math.min(to,i);if(i>h.ix&&c>ci)to=Math.max(to,i)});
 h.to=to;const H=r0.h;
 h.lis.forEach((l,i)=>{if(i===h.ix)return;let t=0;if(h.ix<to&&i>h.ix&&i<=to)t=-H;if(to<h.ix&&i>=to&&i<h.ix)t=H;l.style.transform=t?`translateY(${t}px)`:''});
 const hot=BIN&&h.y>innerHeight-BIN.offsetHeight;if(BIN)BIN.classList.toggle('hot',!!hot);h.hot=!!hot}
function holdMove(x,y){const h=HOLD;if(!h)return false;
 if(!h.on){if(Math.abs(x-h.x0)>8||Math.abs(y-h.y0)>8){clearTimeout(h.t);HOLD=null}return false}
 h.y=y;holdPaint();return true}
function holdEnd(cancel){const h=HOLD;HOLD=null;clearInterval(HOLDAS);if(!h)return;clearTimeout(h.t);if(!h.on)return;
 NOCLICK=true;setTimeout(()=>{NOCLICK=false},350);
 document.body.classList.remove('dragging');binBar(false);
 (h.lis||[]).forEach(l=>{l.style.transform='';l.classList.remove('lift','shift')});
 if(cancel)return;
 if(h.hot){track('scan-hold-rm');return removeAt(h.ix)}
 if(h.to!==h.ix){const items=L.items.filter(i=>IT[i.c]);const [it]=items.splice(h.ix,1);items.splice(h.to,0,it);
  L.items=items.concat(L.items.filter(i=>!IT[i.c]));EXP={};saveL();track('scan-hold-move');render();
  const li=$$('#list .li')[h.to];if(li){li.classList.add('moved');setTimeout(()=>li.classList.remove('moved'),700)}}}
const holdable=t=>!t.closest('input,textarea,select,.vseg,.dys,.ap');
app.addEventListener('touchstart',e=>{if(e.touches.length!==1)return holdEnd(true);const li=e.target.closest('#list .li');if(!li||!holdable(e.target))return;const t=e.touches[0];holdStart(li,t.clientX,t.clientY)},{passive:true});
app.addEventListener('touchmove',e=>{if(!HOLD)return;const t=e.touches[0];if(holdMove(t.clientX,t.clientY))e.preventDefault()},{passive:false});
app.addEventListener('touchend',()=>holdEnd(false));
app.addEventListener('touchcancel',()=>holdEnd(true));
app.addEventListener('mousedown',e=>{if(e.button!==0)return;const li=e.target.closest('#list .li');if(!li||!holdable(e.target))return;holdStart(li,e.clientX,e.clientY)});
addEventListener('mousemove',e=>{if(HOLD){if(holdMove(e.clientX,e.clientY))e.preventDefault()}});
addEventListener('mouseup',()=>holdEnd(false));
app.addEventListener('contextmenu',e=>{if(e.target.closest('#list .li'))e.preventDefault()});
addEventListener('keydown',e=>{if(e.key==='Escape'&&HOLD)holdEnd(true)});

/* ---------- v10: save your protocol (save.js builds the files) ---------- */
/* v10 month view: doses in one vial, cycle length in days (low end; 0 = ongoing), start day */
function perVial(it,x){if(!(canMix(x)||LQ[x.c]))return 0;const p=parseDose(it.dose);if(!p)return 0;const m={kind:p.u==='U'?'units':p.u==='IU'?'iu':p.u==='mL'?'liquid':'mass',vial:+it.vm||defVial(x),water:+it.vw||x.vw||2,dose:p.v,unit:p.u,syr:100};
 if(m.kind==='mass'&&!(m.vial>0))return 0;const r=calc(m,x);return r.ok&&r.per>0?r.per:0}
/* rest after the cycle, from the cycle text ("20 days, 1–2 mo off"); a weekly "5 on/2 off" is not a rest. Selank from its Russian label (repeat after 1–3 weeks) */
function restOf(x){if(x.c==='SLK')return '1–3 wk';const t=String(x.d&&x.d.cycle||'');if(/\d\s*on\s*\/\s*\d\s*off/i.test(t))return '';
 const m=t.match(/([\d.]+(?:\s*[–-]\s*[\d.]+)?\+?)\s*(days?|wk|weeks?|mo|months?)?\s*off/i);if(!m)return '';
 let u=m[2]||(t.match(/\d\s*(days?|wk|weeks?|mo|months?)/i)||[])[1]||'';u=u.replace(/weeks?/i,'wk').replace(/months?/i,'mo').replace(/^days?$/i,'days');return (m[1].replace(/\s+/g,'')+' '+u).trim()}
function cycDays(x){const c=String(x.d&&x.d.cycle||'').trim();if(!c||/ongoing|as needed|continuous|^after/i.test(c))return 0;
 const m=c.match(/([\d.]+)\s*(?:[–-]\s*[\d.]+)?\s*(days?|d\b|wk|weeks?|mo|months?)/i);if(!m)return 0;const n=+m[1],u=m[2].toLowerCase();return Math.round(u[0]==='d'?n:u[0]==='w'?n*7:n*30)}
/* gentle warnings: two or more compounds pushing the same way. Read from each compound's own role line,
   so ones that raise hunger (MK-677, GHRP-2, GHRP-6) or blood sugar (Glucagon), and mouse-only claims, never count */
const CLS={
 glp:['SEM','TRZ','RTA','LIR','EXN','GLP','MAZ','SRV','ORF','RTC','AMC','MAR','PEM','EFO','UBT','VK27','BRN','ECN'],
 ghrh:['CJC','CJD','SRM','TES','CJI','TSI','TIC'],
 ghrelin:['IPA','GP2','GP6','HEX','MK','CJI','TSI','TIC'],
 gh:['HGH'],
 mc:['MT2','MT1','P141']};
function warnings(items){const xs=items.map(it=>IT[it.c]);const has=(x,r)=>x.p===r||(x.r||[]).indexOf(r)>=0;const out=[];
 const say=(n,what)=>n.slice(0,-1).join(', ')+' and '+n[n.length-1]+(n.length>2?' all ':' both ')+what+'.';
 const of=k=>xs.filter(x=>CLS[k].indexOf(x.c)>=0).map(x=>x.n);
 /* doubled up: same drug class twice */
 const glp=of('glp'),ghrh=of('ghrh'),ghr=of('ghrelin'),mc=of('mc'),gh=of('gh');
 if(glp.length>1)out.push(say(glp,'work on GLP-1. That is the same pathway twice: nausea and low blood sugar add up, and most people use one'));
 if(xs.some(x=>x.c==='INS')){const low=xs.filter(x=>x.c!=='INS'&&(CLS.glp.indexOf(x.c)>=0||has(x,'Glucose')&&!/raise|mice|monkeys|claims/i.test((x.ds||{}).Glucose||''))).map(x=>x.n);if(low.length)out.push('Insulin with '+low.join(', ')+': both lower blood sugar. Watch closely for lows.')}
 if(ghrh.length>1)out.push(say(ghrh,'are GHRH analogues. Same receptor, so doubling up adds little'));
 if(ghr.length>1)out.push(say(ghr,'push the ghrelin receptor. Hunger, water retention and blood sugar rise more when stacked'));
 if(gh.length&&(ghrh.length||ghr.length))out.push('Growth hormone with '+ghrh.concat(ghr).filter((v,i,a)=>a.indexOf(v)===i).join(', ')+': growth hormone on top of something that raises it. Water retention, joint aches and blood sugar stack.');
 if(mc.length>1)out.push(say(mc,'act on melanocortin receptors. Nausea, flushing and blood pressure changes add up'));
 /* gentle overlaps, skipped when the GLP-1 warning already covers them */
 if(glp.length<2){
  const app=xs.filter(x=>has(x,'Appetite')&&!/raise|strong hunger/i.test((x.ds||{}).Appetite||'')).map(x=>x.n);
  const glu=xs.filter(x=>has(x,'Glucose')&&!/raise|mice|monkeys|claims/i.test((x.ds||{}).Glucose||'')).map(x=>x.n);
  if(app.length>1&&glu.length>1&&app.join()===glu.join())out.push(say(app,'lower appetite and blood sugar'));
  else{if(app.length>1)out.push(say(app,'lower appetite'));if(glu.length>1&&!xs.some(x=>x.c==='INS'))out.push(say(glu,'lower blood sugar'))}}
 return out}
function exportModel(){const items=L.items.filter(i=>IT[i.c]);const Z=BWREADY?bwLists(items):{b:[],s:[]};
 return {title:L.name?L.name+'’s protocol':'My protocol',date:new Date(),
  items:items.map(it=>{const x=IT[it.c];const d=itemDraw(it);const vm=+it.vm||defVial(x);const tm=it.tm||{};const dd=daysOf(it);
   const vial=LQ[x.c]?`Ready-made ${LQ[x.c].ml} mL vial${LQ[x.c].mg?' ('+LQ[x.c].mg+' mg)':''}, no water`:canMix(x)&&!x.kind?(vm>0?`Vial ${nf(vm,2)} ${isIU(x)?'IU':'mg'} + ${nf(+it.vw||x.vw||2,2)} mL water`:'Vial size not set'):'';
   const mx=canMix(x)&&!x.kind,mixA=LQ[x.c]?`Ready-made ${LQ[x.c].ml} mL`:mx?(vm>0?`${nf(vm,2)} ${isIU(x)?'IU':'mg'} vial`:'Set vial size'):x.rt==='oral'?'Capsule, no mixing':x.rt==='topical'?'On the skin':'',
    mixB=LQ[x.c]?'no water':mx&&vm>0?`+ ${nf(+it.vw||x.vw||2,2)} mL BAC`:'';
   return {n:x.n,c:x.c,col:weights(x).map(w=>[col(w[0]),w[1]]),dose:it.dose||'Dose not set',set:!!it.dose,draw:d,freq:FL[it.f]||'',mixA,mixB,per:perVial(it,x),cyc:cycDays(x),rest:restOf(x),start:it.sd?new Date(it.sd+'T12:00').getTime():0,dy:dd,times:it.f==='D3'?3:it.f==='D2'?2:1,tmA:/AM/.test(tm.a||'')?'AM':/PM/.test(tm.a||'')?'PM':'',tmB:tm.b||'',rk:mx?(x.rt==='nasal'?'nasal':'inj'):x.rt==='oral'?'oral':x.rt==='topical'?'topical':x.rt==='nasal'?'nasal':'inj',
    days:dd.length===7?'Every day':dd.length?dd.map(k=>DL[k]).join(', '):'',time:[tm.a?String(tm.a).replace(/^[^A-Za-z]+/,''):'',tm.b||''].filter(Boolean).join(' · '),
    vial,cycle:cycTxt(x,it),start:it.sd?fdShort(new Date(it.sd+'T12:00').getTime()):'',note:it.nt||'',route:(x.d&&x.d.route)||''}}),
  link:location.origin+protoLink(),
  warn:warnings(items),
  blood:Z.b.map(([id,o])=>({n:o.n,w:o.w})),supp:Z.s.map(([id,o])=>({n:o.n,w:o.w}))}}
function openSave(){const old=$('.sheet10');if(old)old.remove();
 const el=document.createElement('div');el.className='sheet10';el.setAttribute('role','dialog');el.setAttribute('aria-label','Save your protocol');
 el.innerHTML=`<div class="pane"><div class="ph"><h2>Save your protocol</h2><button class="x" data-close>Close</button></div>
 <p class="lede">Your summary protocol: your week, two months ahead, every dose and mix, blood work and supplements, and an easy copy-paste page.</p>
 <div class="sv10">
 <button data-sv="phone">${SVG.phone}<b>Phone PDF</b><span>Pages the size of your screen. Easy to read without zooming.</span></button>
 <button data-sv="img">${SVG.img}<b>Pictures</b><span>PNG, one per page. Saves to your photos.</span></button>
 <button data-sv="paper">${SVG.paper}<b>Paper PDF</b><span>A4 pages for printing or a laptop.</span></button>
 <button data-sv="ai">${SVG.ai}<b>Easy copy-paste</b><span>Your whole protocol as plain text, for your notes or your AI.</span></button>
 </div></div>`;
 document.body.appendChild(el);
 el.addEventListener('click',async e=>{if(e.target===el||e.target.closest('[data-close]'))return el.remove();
  const b=e.target.closest('[data-sv]');if(!b)return;const k=b.dataset.sv;b.classList.add('busy');
  try{await loadBW();BWREADY=true}catch(x){}
  try{if(!window.BSSave)throw new Error('not loaded');const m=exportModel();
   if(k==='ai'){await copy(window.BSSave.aiText(m));track('scan-save-ai')}
   else{await window.BSSave.run(k,m);track('scan-save-'+k)}}
  catch(x){toast('Could not make the file. Try again.')}
  b.classList.remove('busy')})}
window.BS_SCANX={model:exportModel,toast};

